raw_source:
def find_combinations(tuples_list):
    result = []
    for i in range(len(tuples_list)):
        for j in range(i + 1, len(tuples_list)):
            t1 = tuples_list[i]
            t2 = tuples_list[j]
            sum_a = t1[0] + t2[1]
            sum_b = t1[1] + t2[0]
            if (sum_a, sum_b) not in result:
                result.append((sum_a, sum_b))
    return sorted(result)
